             tpd_A_Y : VitalDelayType01 := (0.0453306 ns, 0.0498141 ns);
             tpd_B_Y : VitalDelayType01 := (0.0357049 ns, 0.0397805 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

