             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.0524619 ns;
             tpw_CK_negedge : VitalDelayType := 0.0615605 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.09475 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.09475 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.00100009 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0927498 ns;
             tpd_CK_Q : VitalDelayType01 := (0.0582937 ns, 0.068023 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
