             tpd_CK_Q : VitalDelayType01 := (0.0583284 ns, 0.0720507 ns);
             tpd_SN_Q : VitalDelayType01 := (0.0516374 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
