          NOTIFIER := (
                        Tviol_rec_CK_SN_posedge OR
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_D_CK OR
                        PWviol_SN_negedge OR
                        PWviol_CK );

