             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.09475 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.09475 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.00100009 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.00100009 ns;
