                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_tlat_n0 );

          P0000 := n0_vec(1);

          N5 := VitalINV(P0000);

          ECK_zd := VitalAND2(CK_dly, P0000);

          E_EQ_0 := VitalINV(E_dly);

          SE_EQ_0 := VitalINV(SE_dly);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => ECK,
               OutSignalName => "ECK",
               OutTemp => ECK_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK,
                             TRUE)),
               GlitchData => ECK_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


